Get-WinEvent -FilterHashtable @{LogName='Security';Id=4624;StartTime=(Get-Date).AddDays(-1)} |
  Where-Object { $_.Properties[8].Value -eq 10 } |
  ForEach-Object { [pscustomobject]@{ Time=$_.TimeCreated; User=$_.Properties[5].Value; Src=$_.Properties[18].Value } }

Get-WinEvent -FilterHashtable @{LogName='Security';Id=4672;StartTime=(Get-Date).AddDays(-1)} |
  Where-Object { $_.Properties[1].Value -notin 'SYSTEM','LOCAL SERVICE','NETWORK SERVICE' } |
  Select-Object TimeCreated, @{n='User';e={$_.Properties[1].Value}}, @{n='LogonId';e={$_.Properties[3].Value}}

Get-WinEvent -FilterHashtable @{LogName='Security';Id=4688} |
  Where-Object { $_.Properties[13].Value -match 'winword|excel|powerpnt|outlook' -and $_.Properties[5].Value -match 'cmd|powershell|wscript|cscript|mshta' } |
  Select-Object TimeCreated, @{n='Parent';e={$_.Properties[13].Value}}, @{n='Child';e={$_.Properties[5].Value}}

let monitored = _GetWatchlist("high_value_accounts")
| project UserPrincipalName=tostring(SearchKey), BusinessOwner=tostring(Owner);
SigninLogs
| where TimeGenerated > ago(24h) and ResultType != "0"
| lookup kind=inner monitored on UserPrincipalName
| summarize Failures=count(), Sources=make_set(IPAddress, 20) by UserPrincipalName, BusinessOwner
